 let r=await write(`/api/items/${story.id}/specification/draft`,{expectedDraftVersion:0,baseRevision:0,content},randomUUID(),'ana','PUT');expect(r.statusCode,r.body).toBe(200);r=await write(`/api/items/${story.id}/specification/apply`,{expectedDraftVersion:r.json().draft.version,expectedVersion:1,confirmed:true});expect(r.statusCode,r.body).toBe(200);r=await write(`/api/items/${story.id}/execution`,{expectedVersion:2});expect(r.statusCode,r.body).toBe(200);
 const run=await db.storyExecution.update({where:{id:r.json().runId},data:{state:'succeeded',stage:'completed',commitSha:sha,branch:'sdlc/fixture'}});await db.item.update({where:{id:story.id},data:{status:'merge_request',version:{increment:1}}});await db.workAttempt.updateMany({where:{sourceId:run.id},data:{state:'succeeded',waitingSince:null,finishedAt:new Date()}});
