 const deployPath=`/api/items/${story.id}/development-deployment`,c=(await runtime.app.inject({url:deployPath+'/context',headers:{'x-persona':'ana'}})).json();r=await write(deployPath,{expectedStoryVersion:c.storyVersion,expectedOperationId:null,contextToken:c.token,reason:'Publicar fixture isolada para validar testes reais do domínio.',confirmed:true});expect(r.statusCode,r.body).toBe(200);await runtime.processEnvironmentTargetJobs();await runtime.processDevelopmentDeploymentJobs();const deployment=(await runtime.app.inject(deployPath)).json().deployment;expect(deployment?.state).toBe('succeeded');const task=await db.item.findFirstOrThrow({where:{parentId:story.id,data:{path:['pipelineStage'],equals:'test'}}});for(const kind of ['code_review','security_scan'])await db.qualityCheck.create({data:{executionId:run.id,storyId:story.id,kind,sha,baseSha:'9'.repeat(40),policyVersion:qualityPolicy,state:'passed',actorId:'ana',actorName:'Ana',evidence:{digest:'1'.repeat(64)},finishedAt:new Date()}});
